#!/usr/bin/env python3
"""Hazırlanmış EN/TR belgelerini Mini-Reminder GitHub Wiki'ye aktarır."""

import base64
import io
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
import zipfile


WIKI_URL = "https://github.com/kiviman1/Mini-Reminder.wiki.git"
WIKI_HOME = "https://github.com/kiviman1/Mini-Reminder/wiki"
FALLBACK_OWNER = "kiviman1"
FALLBACK_EMAIL = "217802495+kiviman1@users.noreply.github.com"
COMMIT_MESSAGE = "Add full English and Turkish wiki documentation"


class PublishError(Exception):
    """Kullanıcıya gösterilebilen aktarım hatası."""


def git(arguments, *, cwd=None, action, accepted=(0,)):
    result = subprocess.run(
        ["git", *arguments],
        cwd=cwd,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        errors="replace",
        env={**os.environ, "GIT_TERMINAL_PROMPT": "0"},
    )
    if result.returncode not in accepted:
        details = "\n".join(
            part.strip() for part in (result.stdout, result.stderr) if part.strip()
        )
        raise PublishError(action + ("\n" + details if details else ""))
    return result


def packaged_files():
    try:
        archive_bytes = base64.b64decode(ZIP_PAYLOAD_BASE64, validate=True)
        with zipfile.ZipFile(io.BytesIO(archive_bytes)) as archive:
            names = archive.namelist()
            required = {"Home.md", "Home-TR.md", "_Sidebar.md", "_Footer.md"}
            if (
                len(names) != 64
                or len(set(names)) != 64
                or not required.issubset(names)
                or any(not re.fullmatch(r"[A-Za-z0-9_-]+\.md", name) for name in names)
            ):
                raise PublishError("Belge paketi beklenen 64 Wiki dosyasını içermiyor.")
            return {name: archive.read(name) for name in names}
    except (ValueError, zipfile.BadZipFile, RuntimeError) as error:
        raise PublishError("Gömülü belge paketi okunamadı: " + str(error)) from error


def ensure_identity(directory):
    for key, fallback in (
        ("user.name", FALLBACK_OWNER),
        ("user.email", FALLBACK_EMAIL),
    ):
        current = git(
            ["config", "--get", key],
            cwd=directory,
            action="Git kimliği okunamadı.",
            accepted=(0, 1),
        ).stdout.strip()
        if not current:
            git(
                ["config", "--local", key, fallback],
                cwd=directory,
                action="Geçici Wiki kopyasının Git kimliği ayarlanamadı.",
            )


def main(wiki_url=WIKI_URL):
    if not shutil.which("git"):
        print("Hata: Git bulunamadı. Bu komutu GitHub Codespaces terminalinde çalıştır.", file=sys.stderr)
        return 1

    try:
        files = packaged_files()
        print("Wiki kopyalanıyor; mevcut çalışma klasörlerin korunuyor.", flush=True)
        with tempfile.TemporaryDirectory(prefix="mini-reminder-wiki-") as temporary:
            directory = Path(temporary) / "wiki"
            git(
                ["clone", "--", str(wiki_url), str(directory)],
                action=(
                    "Wiki kopyalanamadı. GitHub'da Wiki'nin Home sayfasının kaydedilmiş "
                    "olduğunu ve bu Codespaces hesabının depoya erişebildiğini kontrol et."
                ),
            )
            branch = git(
                ["symbolic-ref", "--short", "HEAD"],
                cwd=directory,
                action="Wiki'nin varsayılan dalı belirlenemedi.",
            ).stdout.strip()
            for name, contents in files.items():
                target = directory / name
                # Aynı adlı sembolik bağlantıyı izleyip başka bir dosyayı değiştirme.
                if target.is_symlink():
                    target.unlink()
                if target.exists() and not target.is_file():
                    raise PublishError("Wiki dosya adı bir klasörle çakışıyor: " + name)
                target.write_bytes(contents)

            names = sorted(files)
            git(["add", "--", *names], cwd=directory, action="Wiki dosyaları hazırlanamıyor.")
            # Markdown'daki iki boşlukla satır sonlarını olduğu gibi koru.
            git(
                ["-c", "core.whitespace=-blank-at-eol", "diff", "--cached", "--check"],
                cwd=directory,
                action="Belge değişikliklerinin biçim kontrolü başarısız oldu.",
            )
            changed = git(
                ["diff", "--cached", "--quiet"],
                cwd=directory,
                action="Wiki değişiklikleri kontrol edilemedi.",
                accepted=(0, 1),
            ).returncode == 1
            if changed:
                ensure_identity(directory)
                git(
                    ["commit", "-m", COMMIT_MESSAGE],
                    cwd=directory,
                    action="Wiki değişiklikleri kaydedilemedi.",
                )
                print("64 belge hazırlanıp kaydedildi; Wiki'ye gönderiliyor.", flush=True)
            else:
                print("Belgeler zaten aynı; yeni commit gerekmiyor.", flush=True)
            git(
                ["push", "origin", "HEAD:refs/heads/" + branch],
                cwd=directory,
                action=(
                    "Wiki GitHub'a gönderilemedi. Codespaces hesabının Wiki'ye yazma "
                    "yetkisini kontrol et. Başkası Wiki'yi değiştirdiyse komutu yeniden "
                    "çalıştır; zorla gönderim yapılmadı."
                ),
            )

        print("Tamamlandı: 64 EN/TR belge ve ortak menü Wiki'ye aktarıldı.")
        if str(wiki_url) == WIKI_URL:
            print("English: " + WIKI_HOME)
            print("Türkçe: " + WIKI_HOME + "/Home-TR")
        else:
            print("Yerel doğrulama hedefi: " + str(wiki_url))
        return 0
    except (PublishError, OSError) as error:
        print("Hata: " + str(error), file=sys.stderr)
        print("Aktarım tamamlanmadı. Hatanın nedenini giderdikten sonra aynı komutu yeniden çalıştırabilirsin.", file=sys.stderr)
        return 1


# Yalnızca özgün arşivin wiki/ klasöründeki 64 Markdown dosyası.
ZIP_PAYLOAD_BASE64 = ""


if __name__ == "__main__":
    raise SystemExit(main())
